codigo_inicial:
secret = 42
tries = 0
while tries <= 10:
    guess = int(input("Your guess: "))
    tries = tries + 1
    if guess == secret:
        print("Correct!")
        break
    elif guess > secret:
        print("Too high")
    else:
        print("Too low")
if guess != secret:
    print("Game over. The number was 42.")
